from abc import ABCMeta, abstractmethod
from pathlib import Path


class ClientInterface(metaclass=ABCMeta):
    def __init__(self):
        self._used_rmods = []

    @abstractmethod
    def setup(self, *args, **kwargs):
        raise NotImplementedError

    def setup_rmod_connection(self, login, password, port):
        sn = self._setup_rmod_connection(login, password, port)
        self._used_rmods.append(port)
        return sn

    @abstractmethod
    def _setup_rmod_connection(self, login, password, port):
        raise NotImplementedError

    def setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex=None):
        sn = self._setup_custom_rmod_connection(port, login, password, shell_prompt_regex)
        self._used_rmods.append(port)
        return sn

    @abstractmethod
    def _setup_custom_rmod_connection(self, port, login, password, shell_prompt_regex):
        raise NotImplementedError

    @abstractmethod
    def send_command(self, cmd, port, elevated=False, wait_echo=True):
        raise NotImplementedError

    @abstractmethod
    def execute_command(self, cmd, port, elevated=False, timeout=30, wait_echo=True):
        raise NotImplementedError

    @abstractmethod
    def take_snapshot(self, port, timeout=180):
        raise NotImplementedError

    @abstractmethod
    def collect_rmod_output(self, port):
        raise NotImplementedError

    def teardown(self, port=None):
        if port is None:
            for port in self._used_rmods:
                self._teardown_rmod_connection(port)
            self._used_rmods.clear()
        else:
            self._teardown_rmod_connection(port)
            self._used_rmods.remove(port)

    @abstractmethod
    def _teardown_rmod_connection(self, port):
        raise NotImplementedError

    @abstractmethod
    def shutdown(self):
        raise NotImplementedError

    def download_log(self, local_path, port):
        self._ensure_path_exists(local_path)
        return self._download_log(local_path, port)

    @staticmethod
    def _ensure_path_exists(local_path):
        path = Path(local_path).parent
        if not path.is_dir():
            path.mkdir(parents=True)

    @abstractmethod
    def _download_log(self, local_path, port):
        raise NotImplementedError

    @abstractmethod
    def get_rmod_info(self, alias):
        raise NotImplementedError

    @abstractmethod
    def set_rmod_credentials(self, port, login, password, shell_prompt_regex=None):
        raise NotImplementedError

    @property
    def torndown(self):
        return len(self._used_rmods) == 0
